def earliest_not_so_rainy_day(n, x, y, rains):
    stack = []
    result = [None] * n

    for i in range(n):
        while stack and rains[i] < rains[stack[-1]]:
            j = stack.pop()
            left = i - (x + 1)
            right = i + (y + 1)
            if (not left or rains[j] > rains[left]) and (right >= n or rains[j] < rains[right]):
                result[j] = j + 1
        stack.append(i)

    for i in range(n - 1, -1, -1):
        while stack and rains[i] <= rains[stack[-1]]:
            j = stack.pop()
        if result[j] is None:
            result[j] = j + 1

    return next(day for day in range(n) if result[day])

# Example usage
import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
x = int(data[1])
y = int(data[2])
rains = list(map(int, data[3:]))

print(earliest_not_so_rainy_day(n, x, y, rains))
